import React from 'react';
import AdHero from '../components/AdHero';
import AdStrip from '../components/AdStrip';

const Men = () => {
    return (
        <div className="min-h-screen bg-white font-display">
            <AdHero page="men" />
            <AdStrip page="men" />

            <div className="max-w-[1440px] mx-auto py-16 px-6 lg:px-12 text-center">
                <h2 className="text-3xl font-extrabold text-[#10221c] uppercase tracking-tighter">Men's Collection</h2>
                <p className="text-gray-500 mt-4 max-w-2xl mx-auto">Discover the latest in men's luxury fashion, blending classic heritage with modern sporting elegance.</p>
            </div>
        </div>
    );
};

export default Men;
